mapper.select:
SELECT FROM pipe_main
deleted = 0
AND pipe_type = #{pipeType}
AND (pipe_name LIKE CONCAT('%', #{area}, '%') OR pipe_code LIKE CONCAT('%', #{area}, '%'))
AND status = #{status}
ORDER BY created_at DESC, id DESC

mapper.update:
UPDATE pipe_main
pipe_code = #{pipeCode}, pipe_name = #{pipeName}, pipe_type = #{pipeType}, diameter = #{diameter}, material = #{material}, length = #{length}, depth = #{depth}, install_date = #{installDate}, status = #{status}, geom = ST_GeomFromText(#{geomWkt}, 4326), updated_at = #{updatedAt}
WHERE id = #{id} AND deleted = 0
